fix_proposal.sample_rtl:
reg aw_done, w_done;
always @(posedge S_AXI_ACLK) begin
  if (!S_AXI_ARESETN) begin
    axi_awready <= 0; aw_done <= 0;
    axi_wready  <= 0; w_done  <= 0;
    axi_bvalid  <= 0;
  end else begin
    // AW independently
    if (S_AXI_AWVALID && !axi_awready && !aw_done) begin
      axi_awready <= 1; aw_addr_lat <= S_AXI_AWADDR;
    end else axi_awready <= 0;
    if (axi_awready) aw_done <= 1;

    // W independently
    if (S_AXI_WVALID && !axi_wready && !w_done) begin
      axi_wready <= 1; w_data_lat <= S_AXI_WDATA;
    end else axi_wready <= 0;
    if (axi_wready) w_done <= 1;

    // BVALID when both done
    if (aw_done && w_done && !axi_bvalid) axi_bvalid <= 1;
    else if (axi_bvalid && S_AXI_BREADY) begin
      axi_bvalid <= 0; aw_done <= 0; w_done <= 0;
    end
  end
end
